import numbers
import os
import select
import socket
import struct
import sys
import textwrap
import time
import traceback

from threading import Thread, Lock, Event
from importlib import import_module

from pyspark.databricks.utils.memory import clear_memory, get_used_memory
from pyspark.util import _SocketFile, register_sigquit_handler, unregister_sigquit_handler

worker_main_is_running = False
worker_main_is_running_lock = Lock()

# Maximum time to wait for initial bytes on a new connection before treating it
# as a liveness check (used only when indefinite_wait is False).
_INITIAL_DATA_TIMEOUT_SECS = 30


def is_liveness_check(conn, indefinite_wait):
    # Checks if the connection is a liveness check.
    has_data = False
    try:
        if indefinite_wait:
            conn.setblocking(False)
            # select() blocks indefinitely; a closed/empty connection returns
            # readable with recv() returning b"", so has_data stays False.
            readable, _, _ = select.select([conn], [], [])
            if readable and conn.recv(4, socket.MSG_PEEK):
                has_data = True
        else:
            # blocking recv with a fixed timeout; socket.timeout is raised
            # when the deadline is exceeded and caught below.
            conn.settimeout(_INITIAL_DATA_TIMEOUT_SECS)
            if conn.recv(4, socket.MSG_PEEK):
                has_data = True
    except:
        # just print the exception for future generations,
        # as it is more or less unexpected behavior.
        traceback.print_exc(file=sys.stderr)
    return not has_data

def run_worker_main(conn, addr, worker_main, extended_lifetime, disable_threading, is_uds,
                    indefinite_wait):
    """
    Runs the worker_main function. In TCP mode, this is invoked in a separate thread
    because the SafeSpark API server makes connection attempts to check liveliness of
    the worker but disconnects immediately. In UDS mode, this is called directly since
    there is only a single connection. This function will only allow one connection to
    proceed past the initial connection attempt.

    Args:
        conn: Socket connection
        addr: Address (empty string for UDS)
        worker_main: The worker function to execute
        extended_lifetime: Whether to wait after completion
        is_uds: True if using Unix Domain Sockets, False for TCP
        indefinite_wait: If True, wait indefinitely for initial bytes (new behavior);
            if False, use a fixed timeout and raise socket.timeout on expiry (legacy behavior).
    """
    global worker_main_is_running, worker_main_is_running_lock

    # Liveness checks are only relevant for TCP mode (server with multiple connections)
    if not is_uds and is_liveness_check(conn, indefinite_wait):
        conn.close()
        return
    if disable_threading:
        if worker_main_is_running:
            print("worker_main is already running, this is unexpected.")
            sys.exit(os.EX_SOFTWARE)
        worker_main_is_running = True
    else:
        with worker_main_is_running_lock:
            # Beyond simple connection attempts, only one connection should proceed past this point.
            if worker_main_is_running:
                print("worker_main is already running, this is unexpected.")
                sys.exit(os.EX_SOFTWARE)
            worker_main_is_running = True
    print(f"Received bytes, handing over to worker ({conn} {addr})")

    conn.settimeout(None)  # disable timeout, as worker_main does not expect this to be set

    # The following code is very similar to PySpark's daemon.py - we keep running worker_main
    # until we get a non-zero exit code, or SPARK_REUSE_WORKER is not set.
    reuse = os.environ.get("SPARK_REUSE_WORKER", "0") == "1"
    buffer_size = int(os.environ.get("SPARK_BUFFER_SIZE", 65536))

    # TCP-specific socket options (only apply to TCP sockets, not UDS)
    if not is_uds:
        # Here comes specific parameters to control connection between proxy and workerwrap.
        # As it is spark internal config, we consider it safe to transform to int without exception handling.
        tcp_so_write_timeo = int(os.environ.get("SPARK_WRAP_SO_SNDTIMEO", "-1"))
        if tcp_so_write_timeo > 0:
            print("setting SO_SNDTIMEO to ", tcp_so_write_timeo)
            conn.setsockopt(socket.SOL_SOCKET, socket.SO_SNDTIMEO, struct.pack('ll', tcp_so_write_timeo, 0))
        tcp_user_timeout = int(os.environ.get("SPARK_WRAP_TCP_USER_TIMEOUT", "-1"))
        if tcp_user_timeout > 0:
            print("setting TCP_USER_TIMEOUT to ", tcp_user_timeout)
            conn.setsockopt(socket.IPPROTO_TCP, socket.TCP_USER_TIMEOUT, tcp_user_timeout)

    zero_copy_level = os.environ.pop("DB_PYSPARK_ARROW_ZERO_COPY_LEVEL", "off")
    if zero_copy_level != "off":
        infile = _SocketFile(
            input = os.fdopen(os.dup(conn.fileno()), "rb", buffer_size),
            sock = conn,
            create_buffer_copy=zero_copy_level != "arrow_buffer_reuse",
            output = os.fdopen(os.dup(conn.fileno()), "wb", buffer_size)
        )
        # Use a separate outfile for writing — sharing the same _SocketFile object
        # for both infile and outfile causes Arrow IPC corruption because PyArrow's
        # PythonFile wrapper gets confused when the same object is both readable and writable.
        outfile = os.fdopen(os.dup(conn.fileno()), "wb", buffer_size)
    else:
        infile = os.fdopen(os.dup(conn.fileno()), "rb", buffer_size)
        outfile = os.fdopen(os.dup(conn.fileno()), "wb", buffer_size)

    exit_code = 0
    while True:
        try:
            worker_main(infile, outfile)
        except SystemExit as exc:
            print("Exception caught in worker_main:")
            traceback.print_exc()
            if isinstance(exc.code, numbers.Integral):
                exit_code = exc.code
            else:
                exit_code = 1
        finally:
            try:
                outfile.flush()
            except Exception:
                pass
        if reuse and exit_code == 0:
            # To avoid excessive memory usage we clear up memory after each run.
            mem_before = get_used_memory()
            clear_memory()
            mem_after = get_used_memory()
            print(f"worker_main finished with rc=0, reusing worker ({mem_before}->{mem_after})")
            continue
        else:
            print(f"worker_main finished with {exit_code}")
            break

    if extended_lifetime:
        sys.stdout.flush()
        sys.stderr.flush()
        print("Worker is done, waiting to be killed from the outside.", file=sys.stderr)
        Event().wait()
    else:
        conn.close()
        print("run_worker_main finished", file=sys.stderr)
        # When we reach this point, no reuse of the worker is expected by PySpark -
        # we can safely stop the whole process & container.
        sys.exit(0)


def main_tcp(port: int, worker_main, extended_lifetime, disable_threading, indefinite_wait):
    """
    TCP mode: Wait for connections - the API server makes connection attempts to
    check liveliness of the worker, however disconnects immediately.
    
    In TCP mode, the Python worker acts as a server, listening on a port.
    """
    print(f"Starting TCP server mode on port {port}")
    s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    s.bind(("0.0.0.0", port))
    s.listen()
    while True:
        conn, addr = s.accept()
        if disable_threading:
            # In the recent dbrs there is no health check by checking the network connection.
            # Removing the additional thread eliminates the need in GIL, there is nothing to wake up(!)
            # That means that there is expected performance increase on io intensive tasks.
            run_worker_main(conn, addr, worker_main, extended_lifetime, True, False, indefinite_wait)
        else:
            Thread(target=run_worker_main, args=(conn, addr, worker_main, extended_lifetime, False, False, indefinite_wait)).start()


def retry_with_timeout(msg, timeout, interval, fn):
    """Retry fn() until it returns a truthy value or the timeout expires.

    Returns the truthy result of fn() on success, raises TimeoutError otherwise.
    """
    deadline = time.time() + timeout
    while True:
        result = fn()
        if result:
            return result
        if time.time() >= deadline:
            raise TimeoutError(msg)
        time.sleep(min(interval, max(0, deadline - time.time())))


def main_uds(socket_path: str, worker_main, extended_lifetime, disable_threading):
    """
    UDS mode: Connect to Unix Domain Socket created by the runtime.
    
    In UDS mode, the Python worker acts as a client, connecting to a socket
    created by the runtime. This is the inverse of the TCP mode.
    """
    print(f"Starting UDS client mode, connecting to {socket_path}")

    def _try_connect():
        s = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)
        try:
            s.connect(socket_path)
            return s
        except OSError:
            s.close()
            return None

    connect_timeout = int(os.environ.get('UDF_SOCKET_CONNECT_TIMEOUT_SECONDS', '60'))
    conn = retry_with_timeout(
        f"Failed to connect to Unix Domain Socket {socket_path}",
        timeout=connect_timeout,
        interval=0.5,
        fn=_try_connect)

    print(f"Successfully connected to UDS: {socket_path}")

    addr = ""  # UDS doesn't have network addresses

    # Run worker_main directly (no threading needed for single connection)
    try:
        run_worker_main(conn, addr, worker_main, extended_lifetime, disable_threading, is_uds=True,
                        indefinite_wait=True)
    finally:
        conn.close()


def load_worker_main_from_command_args(args):
    """
    Loads the worker main from the command line arguments.
    Returns the worker module and the port.
    """
    if len(args) != 3:
        print("Usage: -m pyspark.databricks.workerwrap <worker_module> <port>")
        sys.exit(os.EX_USAGE)

    _, worker_module, port_arg = args
    imported_module = import_module(worker_module)
    worker_main = getattr(imported_module, "main")

    port = int(port_arg.split(":")[-1])
    return (port, worker_main)

def register_thread_dump_handler() -> None:
    # Register the SIGQUIT handler from the main thread before spawning worker threads.
    # Worker threads call _FaulthandlerHelper.start() which cannot call signal.signal()
    # from a non-main thread, so we must do it here.
    register_sigquit_handler()

def unregister_thread_dump_handler() -> None:
    # Unregister the SIGQUIT handler from the main thread.
    # Used to cleanup in tests.
    unregister_sigquit_handler()

if __name__ == "__main__":
    # Port is always parsed from args for backwards compatibility, but unused in UDS mode.
    port, worker_main = load_worker_main_from_command_args(sys.argv)

    # Check if we should use Unix Domain Sockets or TCP
    socket_path = os.environ.get('UDF_SOCKET_PATH')
    connection_mode = "UDS" if socket_path else "TCP"
    disable_threading = os.environ.get("DB_PYSPARK_DISABLE_THREADING", "false") == "true"
    indefinite_wait = os.environ.pop("DB_PYSPARK_DISABLE_LIVENESS_CHECK_TIMEOUT", "false") == "true"

    startup_info = f"""\
       connection_mode: {connection_mode}
       socket_path: {socket_path if socket_path else 'N/A'}
       port: {port if not socket_path else 'N/A'}
       sys.argv: {sys.argv}
       sys.version_info: {sys.version_info}
       sys.executable: {sys.executable}
       sys.path: {sys.path}
       os.environ: {dict(os.environ)}
       uid: {os.getuid()}
       groups: {os.getgroups()}
       disable_threading: {disable_threading}
       indefinite_wait: {indefinite_wait}"""
    print(textwrap.dedent(startup_info))

    extended_lifetime = os.environ.pop("PYTHON_ISOLATION_EXTENDED_LIFETIME", "false") == "true"

    register_thread_dump_handler()

    # Choose connection mode based on presence of UDF_SOCKET_PATH
    if socket_path:
        main_uds(socket_path, worker_main, extended_lifetime, disable_threading)
    else:
        main_tcp(port, worker_main, extended_lifetime, disable_threading, indefinite_wait)

